@Transactional
public ServiceResult lockRoster(String raceId, String teamId, LockRosterRequest request) {
    List<String> normalizedMembers = normalizeMembers(request.members());
    String rosterKey = rosterKey(raceId, teamId, request.captainBib(), request.expectedVersion(), normalizedMembers);
    return withIdempotency(rosterKey, "LOCK_ROSTER",
        orderedParams("raceId", raceId, "teamId", teamId, "captainBib", ..., "expectedVersion", ..., "members", normalizedMembers),
        () -> {
            RaceRow race = requireOpenRace(raceId, request.expectedVersion());
            TeamRow team = requireTeam(raceId, teamId);
            if (team.status() == TeamStatus.LOCKED) throw new ConflictException("队伍名单已锁定: " + teamId);
            if (!team.captainBib().equals(request.captainBib())) throw new UnprocessableEntityException("仅队长可提交名单锁定");
            validateLockMembers(raceId, teamId, normalizedMembers);
            long now = clock.millis();
            bumpVersion(race, request.expectedVersion());
            int rosterVersion = team.rosterVersion() + 1;
            int raceVersion = request.expectedVersion() + 1;
            repository.insertRosterLock(new RosterLockRow(raceId, teamId, rosterVersion, raceVersion, request.captainBib(), now, false, null, null));
            repository.insertRosterLockMembers(raceId, teamId, rosterVersion, normalizedMembers);
            repository.deleteTeamMembers(raceId, teamId);
